    samples.windows.push({id:entry.id,lane,round,requests:sample.samples.length,elapsedMs:sample.elapsedMs});
   }
   console.log(scenario,'Population',epoch+1,lane,Object.fromEntries(variants.map(v=>[v.id,aggregateSsrThroughput(samples.windows.filter(s=>s.id===v.id&&s.lane===lane)).aggregateRequestsPerSecond])));
  }
  report.epochs.push(samples);await writeFile(path.join(root,'native-http.json'),JSON.stringify(report,null,2));
 }finally{for(const worker of startup.workers)await stopSsrWorker(worker);resetSsrClientConnections();}
 }
 report.summary=Object.fromEntries(['small','rows','data'].map(scenario=>[scenario,Object.fromEntries(['normal','preloaded'].map(lane=>[lane,Object.fromEntries(variants.map(v=>[v.id,aggregateSsrThroughput(report.epochs.filter(e=>e.scenario===scenario).flatMap(e=>e.windows).filter(s=>s.id===v.id&&s.lane===lane))]))]))]));
 report.complete=true;await writeFile(path.join(root,'native-http.json'),JSON.stringify(report,null,2));console.log('FINAL',JSON.stringify(report.summary));
}finally{await service.close();}

