package exactcompiler

import (
	"strconv"

	"github.com/microsoft/typescript-go/internal/ast"
	"github.com/microsoft/typescript-go/internal/printer"
)

// componentPropsSerializationMetadata keeps client tuples inert and associates optional server
// projectors only with repeated finite records. Registration happens once at module evaluation.
func componentPropsSerializationMetadata(factory *printer.NodeFactory, schema *ComponentValueSchema, target Target, imports *componentConstructorImports) *ast.Node {
	if schema == nil {
		return nil
	}
	if target != TargetServer {
		return componentValueSchemaMetadata(factory, schema)
	}
	var emit func(*ComponentValueSchema, bool) *ast.Node
	emit = func(current *ComponentValueSchema, repeated bool) *ast.Node {
		if current == nil || current.Kind == 0 {
			return contractNumber(factory, 0)
		}
		if current.Kind == 2 {
			return contractArray(factory, contractNumber(factory, 2), emit(current.Element, true))
		}
		values := []*ast.Node{contractNumber(factory, 1)}
		for _, field := range current.Fields {
			values = append(values, contractString(factory, field.Name), emit(field.Schema, false))
		}
		metadata := contractArray(factory, values...)
		if !repeated || len(current.Fields) < 4 {
			return metadata
		}
		imports.projectorUsed = true
		return factory.NewCallExpression(factory.NewIdentifier(imports.projectorName), nil, nil, factory.NewNodeList([]*ast.Node{
			metadata, contractNumber(factory, 1), componentPositionalProjector(factory, current),
		}), ast.NodeFlagsNone)
	}
	return emit(schema, false)
}

// projectionEmitter constructs one isolated callback scope. Static field reads retain independent
// inline caches; all authored reads keep live ownership checks and the interpreter's visit order.
type projectionEmitter struct{ factory *printer.NodeFactory }

func (p projectionEmitter) id(name string) *ast.Node { return p.factory.NewIdentifier(name) }
func (p projectionEmitter) prop(value *ast.Node, name string) *ast.Node {
	return p.factory.NewPropertyAccessExpression(value, nil, p.id(name), ast.NodeFlagsNone)
}
func (p projectionEmitter) state(name string) *ast.Node { return p.prop(p.id("state"), name) }
func (p projectionEmitter) call(value *ast.Node, args ...*ast.Node) *ast.Node {
	return p.factory.NewCallExpression(value, nil, nil, p.factory.NewNodeList(args), ast.NodeFlagsNone)
}
func (p projectionEmitter) binary(left *ast.Node, op ast.Kind, right *ast.Node) *ast.Node {
	return p.factory.NewBinaryExpression(nil, left, nil, p.factory.NewToken(op), right)
}
func (p projectionEmitter) block(statements ...*ast.Node) *ast.Node {
	return p.factory.NewBlock(p.factory.NewNodeList(statements), true)
}
func (p projectionEmitter) reject(condition *ast.Node, result *ast.Node) *ast.Node {
	return p.factory.NewIfStatement(condition, p.factory.NewReturnStatement(result), nil)
}
func (p projectionEmitter) constant(name string, value *ast.Node) *ast.Node {
	return p.factory.NewVariableStatement(nil, p.factory.NewVariableDeclarationList(p.factory.NewNodeList([]*ast.Node{
		p.factory.NewVariableDeclaration(p.id(name), nil, nil, value),
	}), ast.NodeFlagsConst))
}
func (p projectionEmitter) index(value *ast.Node, index *ast.Node) *ast.Node {
	return p.factory.NewElementAccessExpression(value, nil, index, ast.NodeFlagsNone)
}

// componentPositionalProjector emits the version-one validation/conversion contract. A failure
// still returns the interpreter's sentinel, and active-path ownership is always released.
func componentPositionalProjector(factory *printer.NodeFactory, schema *ComponentValueSchema) *ast.Node {
	p := projectionEmitter{factory}
	number := func(value int) *ast.Node { return contractNumber(factory, value) }
	not := func(value *ast.Node) *ast.Node {
		return factory.NewPrefixUnaryExpression(ast.KindExclamationToken, value)
	}
	or := func(a, b *ast.Node) *ast.Node { return p.binary(a, ast.KindBarBarToken, b) }
	neq := func(a, b *ast.Node) *ast.Node { return p.binary(a, ast.KindExclamationEqualsEqualsToken, b) }
	eq := func(a, b *ast.Node) *ast.Node { return p.binary(a, ast.KindEqualsEqualsEqualsToken, b) }
	active := func(method string) *ast.Node { return p.call(p.prop(p.state("active"), method), p.id("value")) }
	depth := func() *ast.Node { return p.binary(p.id("depth"), ast.KindPlusToken, number(1)) }
	statements := []*ast.Node{
		p.reject(or(p.binary(factory.NewPrefixUnaryExpression(ast.KindPlusPlusToken, p.state("nodes")), ast.KindGreaterThanToken, p.state("maxNodes")), p.binary(p.id("depth"), ast.KindGreaterThanToken, p.state("maxDepth"))), p.state("unsafe")),
		p.reject(or(or(not(p.id("value")), neq(factory.NewTypeOfExpression(p.id("value")), contractString(factory, "object"))), active("has")), p.state("mismatch")),
		factory.NewExpressionStatement(active("add")),
	}
	body := []*ast.Node{
		p.reject(or(or(p.call(p.prop(p.id("Array"), "isArray"), p.id("value")), neq(p.call(p.prop(p.id("Object"), "getPrototypeOf"), p.id("value")), p.prop(p.id("Object"), "prototype"))), neq(p.prop(p.call(p.prop(p.id("Object"), "keys"), p.id("value")), "length"), number(len(schema.Fields)))), p.state("mismatch")),
		p.constant("output", factory.NewNewExpression(p.id("Array"), nil, factory.NewNodeList([]*ast.Node{number(len(schema.Fields))}))),
	}
	for index, field := range schema.Fields {
		key := contractString(factory, field.Name)
		cell := "cell" + strconv.Itoa(index)
		body = append(body, p.reject(not(p.call(p.prop(p.id("Object"), "hasOwn"), p.id("value"), key)), p.state("mismatch")))
		read := p.index(p.id("value"), contractString(factory, field.Name))
		if field.Schema == nil || field.Schema.Kind == 0 {
			body = append(body, p.constant(cell, read), p.reject(not(p.call(p.state("validate"), p.id(cell), depth(), p.id("state"))), p.state("unsafe")))
		} else {
			body = append(body, p.constant(cell, p.call(p.state("project"), read, p.id("schema"), number(index*2+2), depth(), p.id("state"))), p.reject(or(eq(p.id(cell), p.state("mismatch")), eq(p.id(cell), p.state("unsafe"))), p.id(cell)))
		}
		body = append(body, factory.NewExpressionStatement(p.binary(p.index(p.id("output"), number(index)), ast.KindEqualsToken, p.id(cell))))
	}
	body = append(body, factory.NewReturnStatement(p.id("output")))
	statements = append(statements, factory.NewTryStatement(p.block(body...), nil, p.block(factory.NewExpressionStatement(active("delete")))))
	parameters := []*ast.Node{}
	// Intrinsics are supplied by the runtime so authored Object/Array bindings cannot capture them.
	for _, name := range []string{"value", "depth", "state", "schema", "Object", "Array"} {
		parameters = append(parameters, factory.NewParameterDeclaration(nil, nil, p.id(name), nil, nil, nil))
	}
	return factory.NewArrowFunction(nil, nil, factory.NewNodeList(parameters), nil, nil, factory.NewToken(ast.KindEqualsGreaterThanToken), p.block(statements...))
}

package exactcompiler

import (
	"github.com/microsoft/typescript-go/internal/ast"
	"github.com/microsoft/typescript-go/internal/printer"
)

// lowerComponentContracts attaches a target-local executable artifact to every
// native component. Exported roots may additionally own continuations,
// resumption, and boundary records, but private children are not reduced to a
// ad hoc identity-only callable without executable compiler artifacts.
func lowerComponentContracts(
	sourceFile *ast.SourceFile,
	emitContext *printer.EmitContext,
	components []Component,
	continuations []Continuation,
	resumptions []ComponentResumption,
	boundaries []Boundary,
	target Target,
	identityFilename string,
	preserveComponentHoisting bool,
	compatibility bool,
	projection ComponentContractProjection,
	componentUpdates map[string]string,
	componentInputUpdates map[string]string,
) *ast.SourceFile {
	if target == TargetDefault {
		return sourceFile
	}
	factory := emitContext.Factory
	rootContracts := make(map[string]Component)
	for _, component := range components {
		if componentHasTargetArtifact(component, target) {
			rootContracts[component.Name] = component
		}
	}
	if len(rootContracts) == 0 {
		return sourceFile
	}

	used := sourceIdentifiers(sourceFile)
	descriptorName := allocateGeneratedName(used, "__exactComponentContract")
	constructors := componentConstructorImports{
		renderName:             allocateGeneratedName(used, "__exactConstructRenderComponent"),
		taskName:               allocateGeneratedName(used, "__exactConstructTaskComponent"),
		durableName:            allocateGeneratedName(used, "__exactConstructDurableComponent"),
		directServerName:       allocateGeneratedName(used, "__exactRejectDirectServerConstruction"),
		directLoggingFrameName: allocateGeneratedName(used, "__exactDirectSsrLoggingFrame"),
		directLifecycleName:    allocateGeneratedName(used, "__exactDirectSsrLifecycle"),
		projectorName:          allocateGeneratedName(used, "__exactRegisterPositionalProjector"),
		clientAttachName:       allocateGeneratedName(used, "__exactAttachClientComponent"),
		clientReceiveName:      allocateGeneratedName(used, "__exactReceiveClientProps"),
		clientDisposeName:      allocateGeneratedName(used, "__exactDisposeClientComponent"),
		serverIssueName:        allocateGeneratedName(used, "__exactIssueServerComponent"),
		serverWriteName:        allocateGeneratedName(used, "__exactWriteServerComponent"),
		serverDisposeName:      allocateGeneratedName(used, "__exactDisposeServerComponent"),
	}
	statements := make(
		[]*ast.Node,
		0,
		len(sourceFile.Statements.Nodes)+len(rootContracts)+1,
	)
	hoistedAttachments := make([]*ast.Node, 0)
	for _, statement := range sourceFile.Statements.Nodes {
		if ast.IsFunctionDeclaration(statement) {
			name := statement.Name()
			if name != nil {
				if component, wrap := rootContracts[name.Text()]; wrap {
					preserveHoisting := preserveComponentHoisting ||
						componentFunctionReferencedEarlier(sourceFile, statement, name.Text())
					wrapped := wrapRootComponentFunction(
						emitContext,
						statement.AsFunctionDeclaration(),
						component,
						descriptorName,
						identityFilename,
						continuations,
						resumptions,
						boundaries,
						target,
						used,
						preserveHoisting,
						compatibility,
						projection,
						componentUpdates,
						componentInputUpdates,
						&constructors,
					)
					if preserveHoisting {
						// A function declaration is callable before its textual declaration. Its
						// compiler-owned executable contract must have the same module-order
						// availability, or earlier registries and aliases observe only the bare
						// authored function.
						statements = append(statements, wrapped[0])
						hoistedAttachments = append(hoistedAttachments, wrapped[1:]...)
					} else {
						statements = append(statements, wrapped...)
					}
					continue
				}
			}
		}
		if ast.IsVariableStatement(statement) {
			updatedRoot, rootChanged := wrapRootComponentVariables(
				emitContext,
				statement,
				rootContracts,
				descriptorName,
				identityFilename,
				continuations,
				resumptions,
				boundaries,
				target,
				used,
				compatibility,
				projection,
				componentUpdates,
				componentInputUpdates,
				&constructors,
			)
			if rootChanged {
				statements = append(statements, updatedRoot)
				continue
			}
		}
		statements = append(statements, statement)
	}
	if target == TargetServer {
		for _, component := range components {
			if _, exists := rootContracts[component.Name]; !exists {
				continue
			}
			if component.ClientIslandCount == 0 {
				continue
			}
			if component.Placement == "client" {
				continue
			}
			generatedName := generatedComponentName(
				component.Name,
				"server-part",
				1,
			)
			statements = append(
				statements,
				factory.NewExportDeclaration(
					nil,
					false,
					factory.NewNamedExports(
						factory.NewNodeList([]*ast.Node{
							factory.NewExportSpecifier(
								false,
								factory.NewIdentifier(component.Name),
								factory.NewIdentifier(generatedName),
							),
						}),
					),
					nil,
					nil,
				),
			)
		}
	}
	if len(rootContracts) != 0 {
		updateDefinitions, retained := extractComponentUpdateDefinitions(
			statements,
			componentUpdates,
			componentInputUpdates,
		)
		statements = retained
		insertionIndex := 0
		for insertionIndex < len(statements) {
			statement := statements[insertionIndex]
			if ast.IsImportDeclaration(statement) ||
				isDirectiveStatement(statement) {
				insertionIndex++
				continue
			}
			break
		}
		descriptor := componentDescriptorDeclaration(
			emitContext,
			descriptorName,
		)
		constructorImports := constructors.declarations(factory)
		capacity := len(statements) + len(updateDefinitions) + len(hoistedAttachments) + 1
		capacity += len(constructorImports)
		ordered := make([]*ast.Node, 0, capacity)
		ordered = append(ordered, statements[:insertionIndex]...)
		ordered = append(ordered, constructorImports...)
		ordered = append(ordered, descriptor)
		ordered = append(ordered, updateDefinitions...)
		ordered = append(ordered, hoistedAttachments...)
		ordered = append(ordered, statements[insertionIndex:]...)
		statements = ordered
	}
	result := factory.UpdateSourceFile(
		sourceFile,
		factory.NewNodeList(statements),
		sourceFile.EndOfFileToken,
	).AsSourceFile()
	ast.SetParentInChildren(result.AsNode())
	return result
}

type componentConstructorImports struct {
	projectorName          string
	projectorUsed          bool
	renderName             string
	taskName               string
	durableName            string
	directServerName       string
	directLoggingFrameName string
	directLifecycleName    string
	clientAttachName       string
	clientReceiveName      string
	clientDisposeName      string
	serverIssueName        string
	serverWriteName        string
	serverDisposeName      string
	renderUsed             bool
	taskUsed               bool
	durableUsed            bool
	directServerUsed       bool
	directLoggingFrameUsed bool
	directLifecycleUsed    bool
	clientOperationsUsed   bool
	serverOperationsUsed   bool
}

type componentTargetOperations struct {
	attach  *ast.Node
	receive *ast.Node
	issue   *ast.Node
	write   *ast.Node
	dispose *ast.Node
}

func (imports *componentConstructorImports) targetOperations(
	factory *printer.NodeFactory,
	target Target,
) componentTargetOperations {
	if target == TargetClient {
		imports.clientOperationsUsed = true
		return componentTargetOperations{
			attach:  factory.NewIdentifier(imports.clientAttachName),
			receive: factory.NewIdentifier(imports.clientReceiveName),
			dispose: factory.NewIdentifier(imports.clientDisposeName),
		}
	}
	imports.serverOperationsUsed = true
	return componentTargetOperations{
		issue:   factory.NewIdentifier(imports.serverIssueName),
		write:   factory.NewIdentifier(imports.serverWriteName),
		dispose: factory.NewIdentifier(imports.serverDisposeName),
	}
}

func (imports *componentConstructorImports) selectConstructor(
	factory *printer.NodeFactory,
	abi int,
	directServer bool,
) *ast.Node {
	if directServer {
		imports.directServerUsed = true
		return factory.NewIdentifier(imports.directServerName)
	}
	constructorName := imports.renderName
	if abi&(componentABILifecycle|componentABILists|componentABITasks) == 0 {
		imports.renderUsed = true
	} else if abi&(componentABILifecycle|componentABILists) == 0 && abi&componentABITasks != 0 {
		imports.taskUsed = true
		constructorName = imports.taskName
	} else {
		imports.durableUsed = true
		constructorName = imports.durableName
	}
	return factory.NewIdentifier(constructorName)
}

func componentConstructorImport(
	factory *printer.NodeFactory,
	imported string,
	local string,
	module string,
) *ast.Node {
	declaration := factory.NewImportDeclaration(
		nil,
		factory.NewImportClause(
			ast.KindUnknown,
			nil,
			factory.NewNamedImports(factory.NewNodeList([]*ast.Node{
				factory.NewImportSpecifier(
					false,
					factory.NewIdentifier(imported),
					factory.NewIdentifier(local),
				),
			})),
		),
		factory.NewStringLiteral(module, ast.TokenFlagsNone),
		nil,
	)
	ast.SetParentInChildren(declaration)
	return declaration
}

func (imports *componentConstructorImports) declarations(factory *printer.NodeFactory) []*ast.Node {
	declarations := []*ast.Node{}
	if imports.clientOperationsUsed {
		declarations = append(declarations, componentOperationImports(factory, []componentOperationImport{
			{imported: "attachExactCompiledClientComponent", local: imports.clientAttachName},
			{imported: "receiveExactClientComponentProps", local: imports.clientReceiveName},
			{imported: "disposeExactClientComponent", local: imports.clientDisposeName},
		}))
	}
	if imports.serverOperationsUsed {
		declarations = append(declarations, componentOperationImports(factory, []componentOperationImport{
			{imported: "issueExactServerComponent", local: imports.serverIssueName},
			{imported: "writeExactServerComponent", local: imports.serverWriteName},
			{imported: "disposeExactServerComponent", local: imports.serverDisposeName},
		}))
	}
	if imports.renderUsed {
		declarations = append(declarations, componentConstructorImport(
			factory,
			"constructRenderComponentInstance",
			imports.renderName,
			"@exactjs/core/runtime/component-construction/render",
		))
	}
	if imports.taskUsed {
		declarations = append(declarations, componentConstructorImport(
			factory,
			"constructTaskComponentInstance",
			imports.taskName,
			"@exactjs/core/runtime/component-construction/task",
		))
	}
	if imports.durableUsed {
		declarations = append(declarations, componentConstructorImport(
			factory,
			"constructDurableComponentInstance",
			imports.durableName,
			"@exactjs/core/runtime/component-construction/durable",
		))
	}
	if imports.directServerUsed {
		declarations = append(declarations, componentConstructorImport(
			factory,
			"rejectDirectServerComponentConstruction",
			imports.directServerName,
			"@exactjs/core/runtime/component-construction/direct-server",
		))
	}
	if imports.directLoggingFrameUsed {
		declarations = append(declarations, componentConstructorImport(
			factory,
			"createDirectSsrLoggingFrame",
			imports.directLoggingFrameName,
			"@exactjs/ssr/runtime/direct-logging-frame",
		))
	}
	if imports.directLifecycleUsed {
		declarations = append(declarations, componentConstructorImport(
			factory,
			"directSsrLifecycle",
			imports.directLifecycleName,
			"@exactjs/ssr/runtime/direct-lifecycle",
		))
	}
	if imports.projectorUsed {
		declarations = append(declarations, componentConstructorImport(factory, "registerPositionalProjector", imports.projectorName, "@exactjs/ssr/runtime/positional-projection"))
	}
	return declarations
}

type componentOperationImport struct {
	imported string
	local    string
}

func componentOperationImports(
	factory *printer.NodeFactory,
	operations []componentOperationImport,
) *ast.Node {
	specifiers := make([]*ast.Node, 0, len(operations))
	for _, operation := range operations {
		specifiers = append(specifiers, factory.NewImportSpecifier(
			false,
			factory.NewIdentifier(operation.imported),
			factory.NewIdentifier(operation.local),
		))
	}
	declaration := factory.NewImportDeclaration(
		nil,
		factory.NewImportClause(
			ast.KindUnknown,
			nil,
			factory.NewNamedImports(factory.NewNodeList(specifiers)),
		),
		factory.NewStringLiteral("@exactjs/core/runtime/component-operations", ast.TokenFlagsNone),
		nil,
	)
	ast.SetParentInChildren(declaration)
	return declaration
}

func extractComponentUpdateDefinitions(
	statements []*ast.Node,
	componentUpdates map[string]string,
	componentInputUpdates map[string]string,
) ([]*ast.Node, []*ast.Node) {
	names := make(map[string]struct{}, len(componentUpdates)+len(componentInputUpdates))
	for _, name := range componentUpdates {
		names[name] = struct{}{}
	}
	for _, name := range componentInputUpdates {
		names[name] = struct{}{}
	}
	definitions := make([]*ast.Node, 0, len(names))
	retained := make([]*ast.Node, 0, len(statements))
	for _, statement := range statements {
		if ast.IsVariableStatement(statement) {
			declarations := statement.AsVariableStatement().DeclarationList.
				AsVariableDeclarationList().Declarations.Nodes
			if len(declarations) == 1 {
				name := declarations[0].AsVariableDeclaration().Name()
				if name != nil && ast.IsIdentifier(name) {
					if _, generated := names[name.Text()]; generated {
						definitions = append(definitions, statement)
						continue
					}
				}
			}
		}
		retained = append(retained, statement)
	}
	return definitions, retained
}

func componentFunctionReferencedEarlier(
	sourceFile *ast.SourceFile,
	declaration *ast.Node,
	name string,
) bool {
	for _, statement := range sourceFile.Statements.Nodes {
		if statement == declaration {
			return false
		}
		found := false
		walkNode(statement, func(node *ast.Node) bool {
			if ast.IsIdentifier(node) && node.Text() == name {
				found = true
				return false
			}
			return !found
		})
		if found {
			return true
		}
	}
	return false
}

func componentHasTargetArtifact(component Component, target Target) bool {
	// Partition lowering has already replaced opposite-target implementations
	// with target-local boundary callables. Those stubs are compiled artifacts
	// too; placement does not authorize an identity-only native value.
	return target != TargetDefault && component.TargetArtifact
}

func wrapRootComponentFunction(
	emitContext *printer.EmitContext,
	declaration *ast.FunctionDeclaration,
	component Component,
	descriptorName string,
	identityFilename string,
	continuations []Continuation,
	resumptions []ComponentResumption,
	boundaries []Boundary,
	target Target,
	used map[string]struct{},
	preserveComponentHoisting bool,
	compatibility bool,
	projection ComponentContractProjection,
	componentUpdates map[string]string,
	componentInputUpdates map[string]string,
	constructors *componentConstructorImports,
) []*ast.Node {
	factory := emitContext.Factory
	if target == TargetServer && component.TargetPlan.DirectServerExecutor && declaration.Type != nil {
		declaration = factory.UpdateFunctionDeclaration(
			declaration,
			declaration.Modifiers(),
			declaration.AsteriskToken,
			declaration.Name(),
			declaration.TypeParameters,
			declaration.Parameters,
			nil,
			declaration.FullSignature,
			declaration.Body,
		).AsFunctionDeclaration()
	}
	if !preserveComponentHoisting {
		return wrapRootComponentFunctionValue(
			emitContext,
			declaration,
			component,
			descriptorName,
			identityFilename,
			continuations,
			resumptions,
			boundaries,
			target,
			used,
			compatibility,
			projection,
			componentUpdates,
			componentInputUpdates,
			constructors,
		)
	}
	name := declaration.Name()
	implementationIdentifier := factory.NewIdentifier(name.Text())
	attachment := rootComponentContractAttachment(
		emitContext,
		implementationIdentifier,
		component,
		descriptorName,
		identityFilename,
		continuations,
		resumptions,
		boundaries,
		target,
		declaration.AsNode(),
		used,
		false,
		compatibility,
		projection,
		componentUpdates,
		componentInputUpdates,
		constructors,
	)
	attachmentStatement := factory.NewExpressionStatement(attachment)
	return []*ast.Node{declaration.AsNode(), attachmentStatement}
}

func wrapRootComponentFunctionValue(
	emitContext *printer.EmitContext,
	declaration *ast.FunctionDeclaration,
	component Component,
	descriptorName string,
	identityFilename string,
	continuations []Continuation,
	resumptions []ComponentResumption,
	boundaries []Boundary,
	target Target,
	used map[string]struct{},
	compatibility bool,
	projection ComponentContractProjection,
	componentUpdates map[string]string,
	componentInputUpdates map[string]string,
	constructors *componentConstructorImports,
) []*ast.Node {
	factory := emitContext.Factory
	name := declaration.Name()
	implementationIdentifier := factory.NewIdentifier(
		allocateGeneratedName(used, "__exactImplementation_"+name.Text()),
	)
	functionModifiers := []*ast.Node{}
	if modifiers := declaration.Modifiers(); modifiers != nil {
		for _, modifier := range modifiers.Nodes {
			if modifier.Kind != ast.KindExportKeyword &&
				modifier.Kind != ast.KindDefaultKeyword {
				functionModifiers = append(functionModifiers, modifier)
			}
		}
	}
	var implementationModifiers *ast.ModifierList
	if len(functionModifiers) != 0 {
		implementationModifiers = factory.NewModifierList(functionModifiers)
	}
	implementation := factory.NewFunctionExpression(
		implementationModifiers,
		declaration.AsteriskToken,
		factory.NewIdentifier(name.Text()),
		declaration.TypeParameters,
		declaration.Parameters,
		func() *ast.Node {
			if target == TargetServer && component.TargetPlan.DirectServerExecutor {
				return nil
			}
			return declaration.Type
		}(),
		declaration.FullSignature,
		declaration.Body,
	)
	attachment := rootComponentContractAttachment(
		emitContext,
		implementationIdentifier,
		component,
		descriptorName,
		identityFilename,
		continuations,
		resumptions,
		boundaries,
		target,
		implementation,
		used,
		true,
		compatibility,
		projection,
		componentUpdates,
		componentInputUpdates,
		constructors,
	)
	implementationDeclaration := factory.NewVariableStatement(
		nil,
		factory.NewVariableDeclarationList(
			factory.NewNodeList([]*ast.Node{
				factory.NewVariableDeclaration(
					implementationIdentifier,
					nil,
					nil,
					implementation,
				),
			}),
			ast.NodeFlagsConst,
		),
	)
	defaultExport := ast.HasSyntacticModifier(
		declaration.AsNode(),
		ast.ModifierFlagsDefault,
	)
	var publicModifiers *ast.ModifierList
	if ast.HasSyntacticModifier(declaration.AsNode(), ast.ModifierFlagsExport) &&
		!defaultExport {
		publicModifiers = factory.NewModifierList([]*ast.Node{
			factory.NewModifier(ast.KindExportKeyword),
		})
	}
	publicDeclaration := factory.NewVariableStatement(
		publicModifiers,
		factory.NewVariableDeclarationList(
			factory.NewNodeList([]*ast.Node{
				factory.NewVariableDeclaration(
					factory.NewIdentifier(name.Text()),
					nil,
					nil,
					attachment,
				),
			}),
			ast.NodeFlagsConst,
		),
	)
	result := []*ast.Node{implementationDeclaration, publicDeclaration}
	if defaultExport {
		result = append(
			result,
			factory.NewExportAssignment(
				nil,
				false,
				nil,
				factory.NewIdentifier(name.Text()),
			),
		)
	}
	return result
}

func rootComponentContractAttachment(
	emitContext *printer.EmitContext,
	implementation *ast.Node,
	component Component,
	descriptorName string,
	identityFilename string,
	continuations []Continuation,
	resumptions []ComponentResumption,
	boundaries []Boundary,
	target Target,
	componentFunction *ast.Node,
	used map[string]struct{},
	wrapIIFE bool,
	compatibility bool,
	projection ComponentContractProjection,
	componentUpdates map[string]string,
	componentInputUpdates map[string]string,
	constructors *componentConstructorImports,
) *ast.Node {
	factory := emitContext.Factory
	implementationName := component.Name
	implementationRole := "root"
	rootSymbolID := exactStableID(
		identityFilename,
		"symbol",
		component.ID,
		"root",
		component.Name,
	)
	if target == TargetServer && component.Placement != "client" && component.ClientIslandCount != 0 {
		implementationName = generatedComponentName(
			component.Name,
			"server-part",
			1,
		)
		implementationRole = "server-part"
		rootSymbolID = exactStableID(
			identityFilename,
			component.Name,
			"server-part",
			"1",
		)
	}
	compiledRender := component.CompiledRender ||
		(target == TargetClient && component.ClientCompiledRender)
	implementationRecord := contractObject(factory, false,
		contractProperty(factory, "id", contractString(factory, rootSymbolID)),
		contractProperty(factory, "name", contractString(factory, implementationName)),
		contractProperty(factory, "role", contractString(factory, implementationRole)),
		contractProperty(factory, "implementation", implementation),
	)
	componentContinuations := continuationsForComponent(
		continuations,
		component.ID,
	)
	projectedExecution := componentTargetExecution(component, target)
	runtimeContinuations := componentContinuations
	if target == TargetServer {
		runtimeContinuations = omitDirectServerSetupContinuations(
			componentContinuations,
			component.Execution,
		)
	}
	executors := contractArray(factory)
	if target == TargetServer && projection != ComponentContractProjectionServerRender {
		executors = continuationExecutorMetadata(
			factory,
			componentFunction,
			runtimeContinuations,
			used,
		)
	}
	role := "executor"
	if target == TargetClient {
		role = "client"
	} else if projection == ComponentContractProjectionServerRender {
		role = "render"
	}
	projectedContinuations := continuationMetadata(factory, componentContinuations, target == TargetClient)
	projectedBoundaries := componentBoundaryMetadata(factory, component, boundaries)
	if target == TargetClient && projection == ComponentContractProjectionHydrate {
		// A hydration-only client executes its compiled local task definitions directly and
		// receives server-operation authorization through the serialized hydration config.
		// The verbose composition catalogs are needed only by complete and island clients.
		projectedContinuations = contractArray(factory)
		projectedBoundaries = contractArray(factory)
	}
	usesCompatibility := component.TargetPlan.UsesCompatibility
	hasResumption := component.Placement == "isomorphic" &&
		componentHasResumption(component.ID, resumptions)
	reconstructibleResumption := hasResumption &&
		len(componentContinuations) == 0 &&
		component.TargetPlan.DirectServerFrame &&
		!component.TargetPlan.ServerSurface.ServerLifecycle &&
		componentHasReconstructibleResumption(component.ID, resumptions)
	if reconstructibleResumption {
		hasResumption = false
	}
	directResumption := hasResumption && directServerResumptionSupported(component.ID, resumptions)
	hasInteractions := target == TargetClient && component.Interactions
	hasLifecycle := component.Lifecycle
	targetSurface := componentTargetSurface(component, target)
	if target == TargetServer {
		// Mount/activation registrations are absent from the projected server function.
		// Only lifecycle phases that can run during SSR require the lifecycle ABI there.
		hasLifecycle = targetSurface.ServerLifecycle
	}
	var updates *ast.Node
	if name, exists := componentUpdates[component.Name]; exists {
		updates = factory.NewIdentifier(name)
	}
	var inputs *ast.Node
	if name, exists := componentInputUpdates[component.Name]; exists {
		inputs = factory.NewIdentifier(name)
	}
	serverPublicationName := ""
	if target == TargetServer && hasResumption && len(componentContinuations) != 0 {
		serverPublicationName = component.Name
	}
	var serverFrame *ast.Node
	var serverLifecycle *ast.Node
	if target == TargetServer && component.TargetPlan.DirectServer {
		if targetSurface.Logging {
			constructors.directLoggingFrameUsed = true
			serverFrame = factory.NewIdentifier(constructors.directLoggingFrameName)
		}
		if targetSurface.ServerLifecycle {
			constructors.directLifecycleUsed = true
			serverLifecycle = factory.NewIdentifier(constructors.directLifecycleName)
		}
	}
	runtimeABI := componentRuntimeABI(
		component,
		targetSurface,
		projectedExecution,
		hasLifecycle,
		hasInteractions,
		usesCompatibility,
		compiledRender,
		target == TargetClient && len(componentContinuations) != 0,
	)
	propsSlots := component.PropsSlots
	targetOperations := constructors.targetOperations(factory, target)
	artifact := componentArtifactMetadata(
		factory,
		component.ID,
		target,
		targetOperations,
		implementation,
		constructors.selectConstructor(
			factory,
			runtimeABI,
			target == TargetServer && component.TargetPlan.DirectServer,
		),
		projectedExecution,
		component.TargetPlan.DeferredTaskProps,
		component.StateSlots,
		propsSlots,
		componentPropsSerializationMetadata(factory, component.PropsSerialization, target, constructors),
		runtimeContinuations,
		hasResumption,
		serverPublicationName,
		serverFrame,
		serverLifecycle,
		directResumption,
		hasInteractions,
		usesCompatibility,
		component.DynamicComponents,
		component.Collections,
		component.Targets,
		runtimeABI,
		component.TargetPlan.DirectServer,
		component.TargetPlan.DirectServerExecutor,
		target == TargetServer,
		projection != ComponentContractProjectionComplete,
		updates,
		inputs,
	)
	contractProperties := []*ast.Node{
		contractProperty(
			factory,
			"version",
			factory.NewNumericLiteral("3", ast.TokenFlagsNone),
		),
		contractProperty(
			factory,
			"placement",
			contractString(factory, component.Placement),
		),
		contractProperty(factory, "role", contractString(factory, role)),
		contractProperty(
			factory,
			"implementations",
			contractArray(factory, implementationRecord),
		),
		contractProperty(
			factory,
			"continuations",
			projectedContinuations,
		),
		contractProperty(factory, "executors", executors),
		contractProperty(factory, "boundaries", projectedBoundaries),
		contractProperty(
			factory,
			"artifact",
			artifact,
		),
	}
	if projection == ComponentContractProjectionClient ||
		projection == ComponentContractProjectionHydrate {
		// The build adapter consumes placement, implementation, continuation, executor, and
		// boundary inventories from the compiler's out-of-band build products. A physical client
		// module retains only its executable artifact and optional hydration resumption contract.
		contractProperties = []*ast.Node{contractProperty(factory, "artifact", artifact)}
	}
	if projection != ComponentContractProjectionHydrate &&
		!(target == TargetServer && component.TargetPlan.DirectServer) {
		contractProperties = append(contractProperties, contractProperty(
			factory,
			"execution",
			componentExecutionMetadata(
				factory,
				projectedExecution,
				projection != ComponentContractProjectionComplete,
			),
		))
	}
	if component.Placement == "isomorphic" &&
		projection != ComponentContractProjectionClient &&
		hasResumption {
		contractProperties = append(contractProperties, contractProperty(
			factory,
			"resumption",
			componentResumptionMetadata(
				factory,
				component,
				resumptions,
				boundaries,
				target == TargetServer,
			),
		))
	}
	contract := contractObject(factory, true, contractProperties...)
	brandSymbol := factory.NewComputedPropertyName(
		factory.NewCallExpression(
			factory.NewPropertyAccessExpression(
				factory.NewIdentifier("Symbol"),
				nil,
				factory.NewIdentifier("for"),
				ast.NodeFlagsNone,
			),
			nil,
			nil,
			factory.NewNodeList([]*ast.Node{
				contractString(factory, "@exactjs/component"),
			}),
			ast.NodeFlagsNone,
		),
	)
	properties := factory.NewObjectLiteralExpression(
		factory.NewNodeList([]*ast.Node{
			factory.NewPropertyAssignment(
				nil,
				brandSymbol,
				nil,
				nil,
				contractString(factory, component.ID),
			),
			factory.NewPropertyAssignment(
				nil,
				factory.NewComputedPropertyName(
					factory.NewIdentifier(descriptorName),
				),
				nil,
				nil,
				contract,
			),
		}),
		true,
	)
	assigned := factory.NewCallExpression(
		factory.NewPropertyAccessExpression(
			factory.NewIdentifier("Object"),
			nil,
			factory.NewIdentifier("assign"),
			ast.NodeFlagsNone,
		),
		nil,
		nil,
		factory.NewNodeList([]*ast.Node{implementation, properties}),
		ast.NodeFlagsNone,
	)
	// Compiler metadata is a runtime protocol, not part of an authored component's
	// exported TypeScript surface. Preserve the implementation's callable type so
	// declaration emit cannot expose target-local constructors or contract internals.
	assigned = factory.NewAsExpression(
		assigned,
		factory.NewTypeQueryNode(implementation, nil),
	)
	if !wrapIIFE {
		return assigned
	}
	iife := factory.NewCallExpression(
		factory.NewParenthesizedExpression(
			factory.NewArrowFunction(
				nil,
				nil,
				factory.NewNodeList(nil),
				nil,
				nil,
				factory.NewToken(ast.KindEqualsGreaterThanToken),
				assigned,
			),
		),
		nil,
		nil,
		factory.NewNodeList(nil),
		ast.NodeFlagsNone,
	)
	return emitContext.AddSyntheticLeadingComment(
		iife,
		ast.KindMultiLineCommentTrivia,
		" @__PURE__ ",
		false,
	)
}

func omitDirectServerSetupContinuations(
	continuations []Continuation,
	execution ComponentExecution,
) []Continuation {
	direct := make(map[string]struct{})
	for _, transition := range execution.Transitions {
		if transition.DirectServerSetup {
			direct[transition.ID] = struct{}{}
		}
	}
	if len(direct) == 0 {
		return continuations
	}
	result := make([]Continuation, 0, len(continuations))
	for _, continuation := range continuations {
		if _, omitted := direct[continuation.ID]; !omitted {
			result = append(result, continuation)
		}
	}
	return result
}

func wrapRootComponentVariables(
	emitContext *printer.EmitContext,
	statement *ast.Node,
	components map[string]Component,
	descriptorName string,
	identityFilename string,
	continuations []Continuation,
	resumptions []ComponentResumption,
	boundaries []Boundary,
	target Target,
	used map[string]struct{},
	compatibility bool,
	projection ComponentContractProjection,
	componentUpdates map[string]string,
	componentInputUpdates map[string]string,
	constructors *componentConstructorImports,
) (*ast.Node, bool) {
	factory := emitContext.Factory
	variable := statement.AsVariableStatement()
	list := variable.DeclarationList.AsVariableDeclarationList()
	declarations := append([]*ast.Node(nil), list.Declarations.Nodes...)
	changed := false
	for index, node := range declarations {
		declaration := node.AsVariableDeclaration()
		name := declaration.Name()
		if name == nil || !ast.IsIdentifier(name) ||
			declaration.Initializer == nil {
			continue
		}
		component, wrap := components[name.Text()]
		if !wrap ||
			(!ast.IsArrowFunction(declaration.Initializer) &&
				!ast.IsFunctionExpression(declaration.Initializer)) {
			continue
		}
		implementationName := allocateGeneratedName(
			used,
			"__exactComponentImplementation",
		)
		implementation := factory.NewIdentifier(implementationName)
		implementationDeclaration := factory.NewVariableStatement(
			nil,
			factory.NewVariableDeclarationList(
				factory.NewNodeList([]*ast.Node{
					factory.NewVariableDeclaration(
						implementation,
						nil,
						nil,
						declaration.Initializer,
					),
				}),
				ast.NodeFlagsConst,
			),
		)
		attachment := rootComponentContractAttachment(
			emitContext,
			implementation,
			component,
			descriptorName,
			identityFilename,
			continuations,
			resumptions,
			boundaries,
			target,
			declaration.Initializer,
			used,
			false,
			compatibility,
			projection,
			componentUpdates,
			componentInputUpdates,
			constructors,
		)
		body := factory.NewBlock(
			factory.NewNodeList([]*ast.Node{
				implementationDeclaration,
				factory.NewReturnStatement(attachment),
			}),
			true,
		)
		iife := factory.NewCallExpression(
			factory.NewParenthesizedExpression(
				factory.NewArrowFunction(
					nil,
					nil,
					factory.NewNodeList(nil),
					nil,
					nil,
					factory.NewToken(ast.KindEqualsGreaterThanToken),
					body,
				),
			),
			nil,
			nil,
			factory.NewNodeList(nil),
			ast.NodeFlagsNone,
		)
		declarations[index] = factory.UpdateVariableDeclaration(
			declaration,
			name,
			declaration.ExclamationToken,
			declaration.Type,
			iife,
		)
		changed = true
	}
	if !changed {
		return statement, false
	}
	declarationList := factory.UpdateVariableDeclarationList(
		list,
		factory.NewNodeList(declarations),
		list.Flags,
	)
	return factory.UpdateVariableStatement(
		variable,
		variable.Modifiers(),
		declarationList,
	), true
}

package exactcompiler

import (
	"strconv"
	"strings"

	"github.com/microsoft/typescript-go/internal/ast"
	"github.com/microsoft/typescript-go/internal/printer"
)

// planComponentTargets records the single target-local proof shared by task lowering, contract
// emission, capability selection, and renderer entry lowering. No later pass should reconstruct
// these execution or server-lane decisions from component facts.
func planComponentTargets(
	sourceFile *ast.SourceFile,
	components []Component,
	tasks []Task,
	resumptions []ComponentResumption,
	interop *JSXInterop,
) {
	for index := range components {
		component := &components[index]
		componentNode := componentSourceNode(sourceFile, *component)
		if componentNode == nil {
			continue
		}
		execution := projectComponentExecution(component.Execution, TargetServer)
		serverSurface := projectServerComponentSurface(componentNode, *component, tasks)
		usesCompatibility := componentUsesJSXInterop(*component, componentNode, interop)
		hasLifecycle := serverSurface.ServerLifecycle
		abi := componentRuntimeABI(
			*component,
			serverSurface,
			execution,
			hasLifecycle,
			false,
			usesCompatibility,
			component.CompiledRender,
			false,
		)
		directABI := componentABICompiledRender | componentABITasks | componentABICollections |
			componentABIContexts | componentABILifecycle
		// Every non-client native component owns one direct request-local server artifact. Dynamic
		// selection, resumptions, and focused surfaces change emitted operations, never the lane.
		directServer := component.Placement != "client" && abi&^directABI == 0
		directServerFrame := directServer && len(execution.Transitions) == 0
		component.TargetPlan = ComponentTargetPlan{
			ClientExecution:      projectComponentExecution(component.Execution, TargetClient),
			ServerExecution:      execution,
			ClientSurface:        component.Surface,
			ServerSurface:        serverSurface,
			DeferredTaskProps:    deferredServerTaskProps(*component, execution, componentNode, tasks),
			DirectServer:         directServer,
			DirectServerFrame:    directServerFrame,
			DirectServerExecutor: directServerFrame && directServerExecutorSupported(componentNode),
			UsesCompatibility:    usesCompatibility,
		}
	}
}

// directServerExecutorSupported accepts the normalized single expression render arrow whose body
// can execute immediately after setup without retaining the authored closure.
func directServerExecutorSupported(componentNode *ast.Node) bool {
	returns := directCallableReturns(componentNode)
	if len(returns) != 1 {
		return false
	}
	render := unwrapRenderExpression(returns[0])
	return ast.IsArrowFunction(render) && !ast.IsBlock(render.AsArrowFunction().Body) &&
		containsJSX(render.AsArrowFunction().Body)
}

// directServerLifecycleSupported accepts canonical and extracted named operations that generated
// code can link to the request-local lifecycle sidecar.
func directServerLifecycleSupported(componentNode *ast.Node) bool {
	supported := true
	walkNode(componentNode, func(node *ast.Node) bool {
		if !supported {
			return false
		}
		name, member, dynamic := componentProtocolMember(node)
		if !member || (name != "onUnmount" && name != "onRender" && name != "own") {
			return true
		}
		if dynamic {
			supported = false
			return false
		}
		supported = !dynamic
		return supported
	})
	return supported
}

// directServerReactivitySupported accepts the canonical component convenience operation. Its
// request-local value recomputes on observation, so task-driven plain-frame state writes remain
// fresh without constructing a dependency graph. Named extraction receives a stable focused method.
func directServerReactivitySupported(componentNode *ast.Node) bool {
	supported := true
	walkNode(componentNode, func(node *ast.Node) bool {
		if !supported {
			return false
		}
		name, member, dynamic := componentProtocolMember(node)
		if !member || name != "reactive" {
			return true
		}
		if dynamic {
			supported = false
			return false
		}
		supported = !dynamic
		return supported
	})
	return supported
}

// directServerRefsSupported accepts only ref operations whose complete server semantics can be
// linked to the request-local direct-ref helpers. Named extraction receives stable focused methods.
func directServerRefsSupported(componentNode *ast.Node) bool {
	supported := true
	walkNode(componentNode, func(node *ast.Node) bool {
		if !supported {
			return false
		}
		name, member, dynamic := componentProtocolMember(node)
		if !member || (name != "ref" && name != "readRef" && name != "refs") {
			return true
		}
		if dynamic {
			supported = false
			return false
		}
		supported = !dynamic
		return supported
	})
	return supported
}

func componentTargetSurface(component Component, target Target) ComponentSurfacePlan {
	if target == TargetServer {
		return component.TargetPlan.ServerSurface
	}
	return component.TargetPlan.ClientSurface
}

// projectServerComponentSurface removes only capability uses whose complete expression is erased
// by server lowering. Requirements propagated from external helpers remain conservative because
// their call-site reachability cannot be recovered from a target-neutral boolean summary.
func projectServerComponentSurface(
	componentNode *ast.Node,
	component Component,
	tasks []Task,
) ComponentSurfacePlan {
	result := component.ForwardedSurface
	clientLifecycle := componentClientLifecycleCallbackSpans(componentNode)
	clientTasks := make([]SourceSpan, 0)
	for _, task := range tasks {
		if task.Component != component.Name || task.Placement != "client" {
			continue
		}
		if task.Length != 0 {
			clientTasks = append(clientTasks, SourceSpan{Start: task.Start, Length: task.Length})
		}
		if task.WorkLength != 0 {
			clientTasks = append(clientTasks, SourceSpan{Start: task.WorkStart, Length: task.WorkLength})
		}
	}
	walkNode(componentNode, func(node *ast.Node) bool {
		if insideSourceSpans(node.Pos(), clientLifecycle) || withinAnySourceSpan(node, clientTasks) {
			return false
		}
		if serverErasesJSXAttribute(node, componentNode) {
			return false
		}
		name, member, dynamic := componentProtocolMember(node)
		if !member {
			return true
		}
		mergeComponentSurfaceMember(&result, name, dynamic)
		return true
	})
	return result
}

func serverErasesJSXAttribute(node *ast.Node, componentNode *ast.Node) bool {
	for current := node; current != nil && current != componentNode; current = current.Parent {
		if !ast.IsJsxAttribute(current) {
			continue
		}
		return interactiveJSXAttribute(jsxAttributeText(current.AsJsxAttribute().Name()))
	}
	return false
}

func mergeComponentSurfaceMember(surface *ComponentSurfacePlan, name string, dynamic bool) {
	if dynamic {
		surface.Logging = true
		surface.Localization = true
		surface.Refs = true
		surface.Contexts = true
		surface.Reactivity = true
		surface.ServerLifecycle = true
		return
	}
	switch name {
	case "log":
		surface.Logging = true
	case "intl":
		surface.Localization = true
	case "ref", "readRef", "refs":
		surface.Refs = true
	case "hasContext", "getContext", "setContext":
		surface.Contexts = true
	case "reactive":
		surface.Reactivity = true
	case "onUnmount", "onRender", "own":
		surface.ServerLifecycle = true
	}
}

func directServerTaskSupported(task Task) bool {
	if task.Placement == "client" {
		return true
	}
	// Invoked tasks are continuation operations, not request-render setup. Their generated execute
	// entry belongs to the same artifact but does not require a durable component during SSR.
	if task.Invoked {
		return true
	}
	if directServerSetupComputation(task) {
		return true
	}
	// The direct scheduled frame already owns blocking and nonblocking generations, cancellation,
	// context reads, sibling pre-issuance, and request disposal. Detached and keyed setup lanes still
	// require their dedicated request-local encodings before they may enter this path.
	return !task.Detached && task.KeyLength == 0
}

func componentTargetExecution(component Component, target Target) ComponentExecution {
	if target == TargetServer {
		return component.TargetPlan.ServerExecution
	}
	return component.TargetPlan.ClientExecution
}

// componentExecutionMetadata emits the compact canonical subgraph on both
// target facets so each runtime can optimize without importing its opposite.
func componentExecutionMetadata(
	factory *printer.NodeFactory,
	execution ComponentExecution,
	compact bool,
) *ast.Node {
	ports := make([]*ast.Node, 0, len(execution.Ports))
	for _, port := range execution.Ports {
		ports = append(ports, contractArray(factory,
			contractString(factory, port.Kind),
			contractString(factory, port.Path),
			contractString(factory, port.Direction),
		))
	}
	transitions := make([]*ast.Node, 0, len(execution.Transitions))
	for _, transition := range execution.Transitions {
		transitions = append(transitions, contractArray(factory,
			contractString(factory, transition.ID),
			contractString(factory, transition.TaskID),
			contractString(factory, transition.Activation),
			contractString(factory, transition.Placement),
			contractString(factory, transition.Readiness),
			contractString(factory, transition.Concurrency),
			contractNumberArray(factory, transition.Inputs),
			contractNumberArray(factory, transition.Outputs),
		))
	}
	reactive := make([]*ast.Node, 0, len(execution.Reactive))
	for _, binding := range execution.Reactive {
		reactive = append(reactive, contractObject(factory, true,
			contractProperty(factory, "name", contractString(factory, binding.Name)),
			contractProperty(factory, "provenance", contractString(factory, binding.Provenance)),
			contractProperty(factory, "allocation", contractString(factory, binding.Allocation)),
			contractProperty(factory, "dependencies", stringMetadata(factory, binding.Dependencies)),
		))
	}
	properties := []*ast.Node{
		contractProperty(factory, "version", contractNumber(factory, execution.Version)),
		contractProperty(factory, "ports", contractArray(factory, ports...)),
		contractProperty(factory, "transitions", contractArray(factory, transitions...)),
	}
	if !compact {
		properties = append(properties, contractProperty(factory, "reactive", contractArray(factory, reactive...)))
	}
	return contractObject(factory, true, properties...)
}

// componentArtifactMetadata emits the one current target-discriminated executable carried by a
// native export. Inert continuation and build facts remain outside this runtime artifact.
func componentArtifactMetadata(
	factory *printer.NodeFactory,
	componentID string,
	target Target,
	operations componentTargetOperations,
	instantiate *ast.Node,
	construct *ast.Node,
	execution ComponentExecution,
	deferredTaskProps []string,
	stateSlots []string,
	propsSlots []string,
	propsSerialization *ast.Node,
	continuations []Continuation,
	hasResumption bool,
	serverPublicationName string,
	serverFrame *ast.Node,
	serverLifecycle *ast.Node,
	directResumption bool,
	hasInteractions bool,
	compatibility bool,
	dynamicComponents bool,
	collections bool,
	targets bool,
	runtimeABI int,
	directServer bool,
	directServerExecutor bool,
	server bool,
	compact bool,
	updates *ast.Node,
	inputs *ast.Node,
) *ast.Node {
	state := append([]string{}, stateSlots...)
	props := append([]string{}, propsSlots...)
	tasks := []string{}
	capabilities := []string{}
	for _, transition := range execution.Transitions {
		tasks = append(tasks, transition.ID)
	}
	if len(tasks) != 0 {
		capabilities = append(capabilities, "tasks")
	}
	if len(continuations) != 0 {
		capabilities = append(capabilities, "continuations")
	}
	if hasResumption {
		capabilities = append(capabilities, "resumption")
	}
	if hasInteractions {
		capabilities = append(capabilities, "interactions")
	}
	if compatibility {
		capabilities = append(capabilities, "compatibility")
	}
	if dynamicComponents {
		capabilities = append(capabilities, "dynamic-components")
	}
	if collections {
		capabilities = append(capabilities, "collections")
	}
	if runtimeABI&componentABIContexts != 0 {
		capabilities = append(capabilities, "contexts")
	}
	if targets {
		capabilities = append(capabilities, "targets")
	}
	reactive := make([]*ast.Node, 0, len(execution.Reactive))
	for _, binding := range execution.Reactive {
		reactive = append(reactive, contractObject(factory, true,
			contractProperty(factory, "name", contractString(factory, binding.Name)),
			contractProperty(factory, "provenance", contractString(factory, binding.Provenance)),
			contractProperty(factory, "allocation", contractString(factory, binding.Allocation)),
			contractProperty(factory, "dependencies", stringMetadata(factory, binding.Dependencies)),
		))
	}
	properties := []*ast.Node{
		contractProperty(factory, "version", contractNumber(factory, 1)),
		contractProperty(factory, "target", contractString(factory, string(target))),
		contractProperty(factory, "id", contractString(factory, componentID)),
		contractProperty(factory, "instantiate", instantiate),
		contractProperty(factory, "construct", construct),
		contractProperty(factory, "abi", contractNumber(factory, runtimeABI)),
		contractProperty(factory, "capabilities", stringMetadata(factory, capabilities)),
		contractProperty(factory, "state", stringMetadata(factory, state)),
		contractProperty(factory, "props", stringMetadata(factory, props)),
	}
	if propsSerialization != nil {
		properties = append(properties,
			contractProperty(factory, "serialization", propsSerialization),
		)
	}
	if target == TargetClient {
		properties = append(properties,
			contractProperty(factory, "attach", operations.attach),
			contractProperty(factory, "receive", operations.receive),
			contractProperty(factory, "dispose", operations.dispose),
		)
	} else {
		properties = append(properties,
			contractProperty(factory, "issue", operations.issue),
			contractProperty(factory, "write", operations.write),
			contractProperty(factory, "dispose", operations.dispose),
		)
	}
	if updates != nil {
		properties = append(properties, contractProperty(factory, "updates", updates))
	}
	if inputs != nil {
		properties = append(properties, contractProperty(factory, "inputs", inputs))
	}
	if server {
		statelessDirectExecutor := directServerExecutor && len(state) == 0 &&
			len(capabilities) == 0 && serverFrame == nil && serverLifecycle == nil
		properties = append(properties, contractProperty(
			factory,
			"execution",
			serverComponentExecutionMetadata(
				factory,
				execution,
				deferredTaskProps,
				instantiate,
				directServer,
				directServerExecutor,
				statelessDirectExecutor,
				dynamicComponents,
				serverPublicationName,
				serverFrame,
				serverLifecycle,
			),
		))
	}
	if !compact {
		properties = append(properties,
			contractProperty(factory, "tasks", stringMetadata(factory, tasks)),
			contractProperty(factory, "reactive", contractArray(factory, reactive...)),
			contractProperty(factory, "render", contractString(factory, "returned-function")),
		)
	}
	return contractObject(factory, true, properties...)
}

// serverComponentExecutionMetadata projects activation and dependency slices once at build time.
// The server renderer consumes this record directly instead of reconstructing a per-request DAG.
func serverComponentExecutionMetadata(
	factory *printer.NodeFactory,
	execution ComponentExecution,
	deferredTaskProps []string,
	instantiate *ast.Node,
	direct bool,
	directExecutor bool,
	statelessDirectExecutor bool,
	dynamic bool,
	publicationName string,
	frame *ast.Node,
	lifecycle *ast.Node,
) *ast.Node {
	classification := "synchronous"
	if dynamic && !direct {
		classification = "dynamic"
	} else if len(execution.Transitions) != 0 {
		classification = "scheduled"
	}
	lane := "direct"
	properties := []*ast.Node{
		contractProperty(factory, "version", contractNumber(factory, 1)),
		contractProperty(factory, "classification", contractString(factory, classification)),
		contractProperty(factory, "lane", contractString(factory, lane)),
	}
	if len(deferredTaskProps) != 0 {
		properties = append(properties,
			contractProperty(factory, "deferredTaskProps", stringMetadata(factory, deferredTaskProps)),
		)
	}
	if lane == "direct" {
		properties = append(properties,
			contractProperty(factory, "render", instantiate),
		)
		if statelessDirectExecutor {
			properties = append(properties,
				contractProperty(factory, "mode", contractString(factory, "stateless")),
			)
		} else if directExecutor {
			properties = append(properties,
				contractProperty(factory, "mode", contractString(factory, "direct")),
			)
		}
		if frame != nil {
			properties = append(properties, contractProperty(factory, "frame", frame))
		}
		if lifecycle != nil {
			properties = append(properties, contractProperty(factory, "lifecycle", lifecycle))
		}
	}
	if publicationName != "" {
		properties = append(properties, contractProperty(factory, "publication", contractObject(
			factory,
			true,
			contractProperty(factory, "kind", contractString(factory, "resumption")),
			contractProperty(factory, "name", contractString(factory, publicationName)),
		)))
	}
	return contractObject(factory, true, properties...)
}

func serverSetupTaskPropNames(execution ComponentExecution) []string {
	seen := make(map[string]struct{})
	result := []string{}
	for _, transition := range execution.Transitions {
		if transition.Activation != "setup" {
			continue
		}
		for _, input := range transition.Inputs {
			if input < 0 || input >= len(execution.Ports) || execution.Ports[input].Kind != "props" {
				continue
			}
			path := strings.TrimPrefix(execution.Ports[input].Path, "props.")
			if separator := strings.IndexByte(path, '.'); separator >= 0 {
				path = path[:separator]
			}
			if path == "" {
				continue
			}
			if _, exists := seen[path]; exists {
				continue
			}
			seen[path] = struct{}{}
			result = append(result, path)
		}
	}
	return result
}

// deferredServerTaskProps proves which setup-task inputs are never consumed by ordinary
// component construction or rendering. Only those props may retain dependency provenance while
// the component is instantiated; every other pending prop must settle first.
func deferredServerTaskProps(
	component Component,
	execution ComponentExecution,
	componentNode *ast.Node,
	tasks []Task,
) []string {
	candidates := serverSetupTaskPropNames(execution)
	if len(candidates) == 0 || componentNode == nil {
		return candidates
	}
	propsName := componentPropsParameterName(componentNode)
	if propsName == "" {
		return nil
	}
	candidateSet := make(map[string]struct{}, len(candidates))
	for _, name := range candidates {
		candidateSet[name] = struct{}{}
	}
	taskRanges := make([]SourceSpan, 0, len(tasks)*2)
	for _, task := range tasks {
		if task.Component != component.Name || task.Invoked ||
			(task.Placement != "server" && task.Placement != "isomorphic") {
			continue
		}
		if task.Length > 0 {
			taskRanges = append(taskRanges, SourceSpan{Start: task.Start, Length: task.Length})
		}
		if task.WorkLength > 0 {
			taskRanges = append(taskRanges, SourceSpan{Start: task.WorkStart, Length: task.WorkLength})
		}
	}
	direct := make(map[string]struct{})
	walkNode(componentNode, func(node *ast.Node) bool {
		name, ok := rootPropertyName(node, propsName)
		if !ok {
			return true
		}
		if _, candidate := candidateSet[name]; !candidate || withinAnySourceSpan(node, taskRanges) {
			return true
		}
		direct[name] = struct{}{}
		return true
	})
	result := make([]string, 0, len(candidates))
	for _, name := range candidates {
		if _, usedDirectly := direct[name]; !usedDirectly {
			result = append(result, name)
		}
	}
	return result
}

func componentPropsParameterName(componentNode *ast.Node) string {
	for _, parameter := range componentNode.Parameters() {
		name := parameter.Name()
		if name != nil && ast.IsIdentifier(name) && name.Text() != "this" {
			return name.Text()
		}
	}
	return ""
}

func rootPropertyName(node *ast.Node, receiver string) (string, bool) {
	switch {
	case ast.IsPropertyAccessExpression(node):
		member := node.AsPropertyAccessExpression()
		if ast.IsIdentifier(member.Expression) && member.Expression.Text() == receiver &&
			member.Name() != nil {
			return member.Name().Text(), true
		}
	case ast.IsElementAccessExpression(node):
		member := node.AsElementAccessExpression()
		if ast.IsIdentifier(member.Expression) && member.Expression.Text() == receiver &&
			member.ArgumentExpression != nil && ast.IsStringLiteral(member.ArgumentExpression) {
			return member.ArgumentExpression.Text(), true
		}
	}
	return "", false
}

func withinAnySourceSpan(node *ast.Node, spans []SourceSpan) bool {
	for _, span := range spans {
		if node.Pos() >= span.Start && node.End() <= span.Start+span.Length {
			return true
		}
	}
	return false
}

// componentRuntimeABI compacts compiler-proven execution needs into the hot construction record.
func componentRuntimeABI(
	component Component,
	surface ComponentSurfacePlan,
	execution ComponentExecution,
	hasLifecycle bool,
	hasInteractions bool,
	compatibility bool,
	compiledRender bool,
	continuationDispatch bool,
) int {
	abi := 0
	rangeOutput := compiledRender && component.ClientRangeOutput
	if compiledRender && !rangeOutput {
		abi |= componentABICompiledRender
	}
	if rangeOutput {
		abi |= componentABIRangeOutput
	}
	if hasLifecycle {
		abi |= componentABILifecycle
	}
	if component.Lists {
		abi |= componentABILists
	}
	if len(execution.Transitions) != 0 || compatibility || continuationDispatch {
		abi |= componentABITasks
	}
	if component.Collections {
		abi |= componentABICollections
	}
	if surface.Contexts || surface.Localization {
		abi |= componentABIContexts
	}
	return abi
}

// projectComponentExecution removes opposite-target transitions and compacts
// their now-unreachable ports before metadata reaches a physical artifact.
func projectComponentExecution(execution ComponentExecution, target Target) ComponentExecution {
	transitions := []ComponentTransition{}
	usedPorts := make(map[int]struct{})
	inputPorts := make(map[int]struct{})
	outputPorts := make(map[int]struct{})
	for _, transition := range execution.Transitions {
		if (target == TargetClient && transition.Placement == "server") ||
			(target == TargetServer &&
				(transition.Placement == "client" || transition.DirectServerSetup)) {
			continue
		}
		transitions = append(transitions, transition)
		for _, input := range transition.Inputs {
			usedPorts[input] = struct{}{}
			inputPorts[input] = struct{}{}
		}
		for _, output := range transition.Outputs {
			usedPorts[output] = struct{}{}
			outputPorts[output] = struct{}{}
		}
	}
	ports := []ComponentPort{}
	remap := make(map[int]int, len(usedPorts))
	for _, port := range execution.Ports {
		if _, used := usedPorts[port.Index]; !used {
			continue
		}
		oldIndex := port.Index
		port.Index = len(ports)
		remap[oldIndex] = port.Index
		_, input := inputPorts[oldIndex]
		_, output := outputPorts[oldIndex]
		switch {
		case input && output:
			port.Direction = "inout"
		case output:
			port.Direction = "output"
		default:
			port.Direction = "input"
		}
		ports = append(ports, port)
	}
	for index := range transitions {
		transitions[index].Inputs = remapComponentPorts(transitions[index].Inputs, remap)
		transitions[index].Outputs = remapComponentPorts(transitions[index].Outputs, remap)
	}
	return ComponentExecution{
		Version: execution.Version, Ports: ports, Transitions: transitions,
		Reactive: append([]ReactiveAllocation{}, execution.Reactive...),
	}
}

func remapComponentPorts(values []int, indexes map[int]int) []int {
	result := make([]int, 0, len(values))
	for _, value := range values {
		if mapped, exists := indexes[value]; exists {
			result = append(result, mapped)
		}
	}
	return result
}

func continuationDependencyMetadata(
	factory *printer.NodeFactory,
	dependencies []TaskDependency,
) []*ast.Node {
	values := make([]*ast.Node, 0, len(dependencies))
	for _, dependency := range dependencies {
		properties := []*ast.Node{
			contractProperty(factory, "index", contractNumber(factory, dependency.Index)),
			contractProperty(factory, "source", contractString(factory, dependency.Source)),
		}
		if dependency.Path != "" {
			properties = append(properties,
				contractProperty(factory, "path", contractString(factory, dependency.Path)),
			)
		}
		values = append(values, contractObject(factory, true, properties...))
	}
	return values
}

func contractNumber(factory *printer.NodeFactory, value int) *ast.Node {
	return factory.NewNumericLiteral(strconv.Itoa(value), ast.TokenFlagsNone)
}

func contractNumberArray(factory *printer.NodeFactory, values []int) *ast.Node {
	nodes := make([]*ast.Node, 0, len(values))
	for _, value := range values {
		nodes = append(nodes, contractNumber(factory, value))
	}
	return contractArray(factory, nodes...)
}

